select private.rc_release_guide(
  p_slug => 'log-station-ids',
  p_tool_key => 'log',
  p_title => 'Station IDs',
  p_summary => 'Where each clock''s hourly legal ID goes, and pinning one so every hour has an ID.',
  p_screen_keys => array['log.station-ids'],
  p_sort_order => 44,
  p_version_note => 'Station IDs',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Station IDs lists every clock a program airs on, where its hourly legal ID goes, and the legal IDs pinned there. Open it from "},{"type":"text","text":"Programs","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Reading the list"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each clock shows the programs that air on it and how many hours it runs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every hour has an ID","marks":[{"type":"bold"}]},{"type":"text","text":": a legal ID is pinned for each hour on every day the clock airs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Some hours have no ID","marks":[{"type":"bold"}]},{"type":"text","text":" names the hours, and the days, still open."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No ID pinned","marks":[{"type":"bold"}]},{"type":"text","text":": the clock has an ID position but nothing in it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No ID position","marks":[{"type":"bold"}]},{"type":"text","text":": no break on the clock takes a legal ID. The program director marks one on the clock page, usually the last break before the top of the hour."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pinning a legal ID"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under an ID position, choose "},{"type":"text","text":"Pin a legal ID","marks":[{"type":"bold"}]},{"type":"text","text":", pick the ID, and choose the hour and days. Leaving the hour on "},{"type":"text","text":"Every hour","marks":[{"type":"bold"}]},{"type":"text","text":" and no days selected pins it everywhere."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A pinned ID goes into every rundown made from that clock from then on. Rundowns already made keep what they have."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" takes a pin off; nothing is deleted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The program director or traffic can pin and remove IDs. Everyone else can read the page."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs on the placeholder clock have no ID position until their network clock is added."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only approved legal IDs from the content library can be pinned."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-dashboard',
  p_tool_key => 'underwriting',
  p_title => 'The dashboard',
  p_summary => 'What needs attention today, grouped by job: missed credits, scheduling, and affidavits.',
  p_screen_keys => array['underwriting.dashboard'],
  p_sort_order => 10,
  p_version_note => 'To record in DAD, and the log of record',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dashboard opens on what needs attention, in three groups. Every number links to the list it counts, filtered the same way."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Missed credits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Need a decision","marks":[{"type":"bold"}]},{"type":"text","text":": an exception with no makegood yet, or one the agency declined."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiting on the agency","marks":[{"type":"bold"}]},{"type":"text","text":": the order's makegoods need the agency's approval, and no answer is recorded yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegoods awaiting a break","marks":[{"type":"bold"}]},{"type":"text","text":": the next auto-fill places these first."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scheduling"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Units not yet scheduled","marks":[{"type":"bold"}]},{"type":"text","text":": open periods on active contracts that auto-fill hasn't reached yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity conflicts","marks":[{"type":"bold"}]},{"type":"text","text":": lines that can't be placed in the next 14 days, listed below with what's blocking each one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To record in DAD","marks":[{"type":"bold"}]},{"type":"text","text":": messages under a new DAD cut that production hasn't marked recorded yet."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Affidavits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To generate","marks":[{"type":"bold"}]},{"type":"text","text":": contracts with aired credits not yet covered by an affidavit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Awaiting your signature","marks":[{"type":"bold"}]},{"type":"text","text":": generated affidavits ready to sign. Only underwriting managers see this one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Auto-fill everything","marks":[{"type":"bold"}]},{"type":"text","text":" in the right-hand column to fill every active contract's open periods, makegoods first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you can open Log, "},{"type":"text","text":"Log of record","marks":[{"type":"bold"}]},{"type":"text","text":" in the right-hand column shows whether the DAD log is released for today and the next two days, and links to "},{"type":"text","text":"Station IDs","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-02-log-station-ids',
  p_tool_key => 'log',
  p_released_on => '2026-10-02',
  p_title => 'Station IDs, and the log of record on the traffic dashboard',
  p_guide_slugs => array['log-station-ids', 'underwriting-dashboard'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A new Station IDs page, reached from Programs, shows every clock's ID position and which hours have a legal ID pinned. The program director or traffic can pin and remove IDs there without opening each clock. The Underwriting & Traffic dashboard now shows whether the DAD log is released for the next three days and counts messages still to record in DAD."}]}]}$body$
);
